FOR ()-[r:SUPPORTS]-() REQUIRE r.supportId IS UNIQUE;
CREATE CONSTRAINT treats_fact_id IF NOT EXISTS
FOR ()-[r:TREATS]-() REQUIRE r.factId IS UNIQUE;

// Reset only a disposable demo database.
MATCH (n) DETACH DELETE n;

CREATE CONSTRAINT document_id IF NOT EXISTS
FOR (d:Document) REQUIRE d.documentId IS UNIQUE;
CREATE CONSTRAINT chunk_id IF NOT EXISTS
FOR (c:Chunk) REQUIRE c.chunkId IS UNIQUE;
CREATE CONSTRAINT entity_id IF NOT EXISTS
FOR (e:Entity) REQUIRE e.entityId IS UNIQUE;
CREATE CONSTRAINT mention_id IF NOT EXISTS
FOR (m:EntityMention) REQUIRE m.mentionId IS UNIQUE;
CREATE CONSTRAINT fact_id IF NOT EXISTS
FOR (f:Fact) REQUIRE f.factId IS UNIQUE;
CREATE CONSTRAINT evidence_id IF NOT EXISTS
FOR (e:Evidence) REQUIRE e.evidenceId IS UNIQUE;
CREATE CONSTRAINT treats_fact_id IF NOT EXISTS
FOR ()-[r:TREATS]-() REQUIRE r.factId IS UNIQUE;

// The review addresses one occurrence without changing the canonical Fact.
MATCH (e:Evidence {evidenceId: 'DOC-1-C1|RUN-1|OCC-1'})
SET e.reviewStatus = 'ACCEPTED',
    e.reviewedBy = 'demo-reviewer',
    e.reviewedAt = datetime()
RETURN e;
